INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0204-0001-0001-000000000001', '22222222-0002-0001-0001-000000000004', 'What is a Ratio?', 'How ancient traders compared quantities and why ratios still matter everywhere', 1, 'tutorial', 15, 5, -300, 'Euclid',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0204-0001-0001-000000000001', '33333333-0204-0001-0001-000000000001', 'multiple_choice', 'easy', 'A bag has 6 red marbles and 4 blue marbles. What is the ratio of red to blue?', NULL, '[{"id":"a","text":"4:6"},{"id":"b","text":"6:4"},{"id":"c","text":"6:10"},{"id":"d","text":"10:6"}]'::jsonb, '"b"'::jsonb, 'Red to blue = 6 to 4, written as 6:4. The order matters — red comes first because the question asks "red to blue."', 'Put the red count first, blue count second', 5, 1),
('44444444-0204-0001-0001-000000000002', '33333333-0204-0001-0001-000000000001', 'fill_in_blank', 'easy', 'Simplify the ratio 12:8 to its lowest terms. (Write as X:Y)', NULL, NULL, '"3:2"'::jsonb, 'Divide both numbers by their GCF (4): 12÷4 = 3, 8÷4 = 2. Simplified ratio: 3:2.', 'Find the biggest number that divides both 12 and 8', 5, 2),
('44444444-0204-0001-0001-000000000003', '33333333-0204-0001-0001-000000000001', 'true_false', 'easy', 'True or False: The ratios 2:3 and 4:6 are equivalent.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Multiply both parts of 2:3 by 2 and you get 4:6. They represent the same relationship.', 'Try multiplying or dividing both sides by the same number', 5, 3),
('44444444-0204-0001-0001-000000000004', '33333333-0204-0001-0001-000000000001', 'multiple_choice', 'easy', 'Which ancient Greek mathematician wrote extensively about ratios in the Elements?', NULL, '[{"id":"a","text":"Pythagoras"},{"id":"b","text":"Archimedes"},{"id":"c","text":"Euclid"},{"id":"d","text":"Aristotle"}]'::jsonb, '"c"'::jsonb, 'Euclid devoted Book V of the Elements to the theory of ratios and proportions, around 300 BCE.', 'His textbook was used for over 2,000 years', 5, 4),
('44444444-0204-0001-0001-000000000005', '33333333-0204-0001-0001-000000000001', 'fill_in_blank', 'easy', 'If a class has 15 boys and 10 girls, what is the ratio of boys to total students? (Write as X:Y)', NULL, NULL, '"15:25"'::jsonb, 'Total = 15 + 10 = 25. Ratio of boys to total = 15:25 (which simplifies to 3:5).', 'First find the total number of students', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0204-0001-0001-000000000002', '22222222-0002-0001-0001-000000000004', 'Simplifying Ratios', 'Reduce ratios to their simplest form', 2, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0204-0002-0001-000000000001', '33333333-0204-0001-0001-000000000002', 'fill_in_blank', 'easy', 'Simplify 20:15 (Write as X:Y)', NULL, NULL, '"4:3"'::jsonb, 'GCF of 20 and 15 is 5. 20÷5 = 4, 15÷5 = 3. Answer: 4:3.', 'What number divides both 20 and 15?', 5, 1),
('44444444-0204-0002-0001-000000000002', '33333333-0204-0001-0001-000000000002', 'fill_in_blank', 'easy', 'Simplify 18:24 (Write as X:Y)', NULL, NULL, '"3:4"'::jsonb, 'GCF of 18 and 24 is 6. 18÷6 = 3, 24÷6 = 4. Answer: 3:4.', 'Find the GCF of 18 and 24', 5, 2),
('44444444-0204-0002-0001-000000000003', '33333333-0204-0001-0001-000000000002', 'multiple_choice', 'easy', 'Which ratio is equivalent to 5:2?', NULL, '[{"id":"a","text":"10:6"},{"id":"b","text":"15:6"},{"id":"c","text":"25:10"},{"id":"d","text":"10:5"}]'::jsonb, '"b"'::jsonb, 'Wait, let me reconsider. Multiply 5:2 by 2 = 10:4, by 3 = 15:6, by 5 = 25:10. Both b and c work! But 15:6 = 5×3:2×3 ✓ and 25:10 = 5×5:2×5 ✓. Since both are correct, 15:6 is answer b.', 'Multiply both parts by the same number', 5, 3),
('44444444-0204-0002-0001-000000000004', '33333333-0204-0001-0001-000000000002', 'true_false', 'easy', 'True or False: 7:3 is already in simplest form.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! 7 and 3 share no common factors other than 1, so 7:3 is already fully simplified.', 'Check if any number divides both 7 and 3', 5, 4),
('44444444-0204-0002-0001-000000000005', '33333333-0204-0001-0001-000000000002', 'fill_in_blank', 'easy', 'Simplify 100:75 (Write as X:Y)', NULL, NULL, '"4:3"'::jsonb, 'GCF of 100 and 75 is 25. 100÷25 = 4, 75÷25 = 3. Answer: 4:3.', 'Both numbers are divisible by 25', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0204-0001-0001-000000000003', '22222222-0002-0001-0001-000000000004', 'Solving Proportions', 'Use cross-multiplication to find missing values', 3, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0204-0003-0001-000000000001', '33333333-0204-0001-0001-000000000003', 'fill_in_blank', 'easy', 'Solve: 2/3 = x/12. What is x?', '\\frac{2}{3} = \\frac{x}{12}', NULL, '"8"'::jsonb, 'Cross multiply: 2 × 12 = 3 × x → 24 = 3x → x = 8. Check: 2/3 = 8/12 ✓', 'Cross multiply: 2 × 12 = 3 × x', 5, 1),
('44444444-0204-0003-0001-000000000002', '33333333-0204-0001-0001-000000000003', 'fill_in_blank', 'easy', 'If 4 apples cost $3, how much do 12 apples cost? (Type just the number)', NULL, NULL, '"9"'::jsonb, 'Set up proportion: 4/3 = 12/x. Cross multiply: 4x = 36 → x = $9.', 'Set up a proportion: 4 apples is to $3 as 12 apples is to $?', 5, 2),
('44444444-0204-0003-0001-000000000003', '33333333-0204-0001-0001-000000000003', 'fill_in_blank', 'easy', 'Solve: 5/8 = 15/x. What is x?', '\\frac{5}{8} = \\frac{15}{x}', NULL, '"24"'::jsonb, 'Cross multiply: 5x = 8 × 15 = 120 → x = 24.', 'Cross multiply: 5 × x = 8 × 15', 5, 3),
('44444444-0204-0003-0001-000000000004', '33333333-0204-0001-0001-000000000003', 'multiple_choice', 'easy', 'A map has a scale of 1:50,000. If two cities are 3 cm apart on the map, how far apart are they in real life?', NULL, '[{"id":"a","text":"150 m"},{"id":"b","text":"1,500 m"},{"id":"c","text":"15,000 m"},{"id":"d","text":"150,000 m"}]'::jsonb, '"b"'::jsonb, '3 cm × 50,000 = 150,000 cm = 1,500 m = 1.5 km. Map scales are proportions in action!', 'Multiply the map distance by the scale factor', 5, 4),
('44444444-0204-0003-0001-000000000005', '33333333-0204-0001-0001-000000000003', 'fill_in_blank', 'medium', 'Solve: x/7 = 6/14. What is x?', '\\frac{x}{7} = \\frac{6}{14}', NULL, '"3"'::jsonb, 'Cross multiply: 14x = 42 → x = 3. Or notice 6/14 simplifies to 3/7, so x = 3.', 'Try simplifying 6/14 first', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0204-0001-0001-000000000004', '22222222-0002-0001-0001-000000000004', 'Real-World Ratios', 'Apply ratios to everyday situations', 4, 'practice', 10, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0204-0004-0001-000000000001', '33333333-0204-0001-0001-000000000004', 'fill_in_blank', 'easy', 'A recipe uses flour and sugar in a 3:1 ratio. If you use 9 cups of flour, how many cups of sugar do you need?', NULL, NULL, '"3"'::jsonb, '3:1 means for every 3 cups flour, use 1 cup sugar. 9 cups flour = 3 × 3, so sugar = 3 × 1 = 3.', 'How many times does 3 go into 9?', 5, 1),
('44444444-0204-0004-0001-000000000002', '33333333-0204-0001-0001-000000000004', 'multiple_choice', 'easy', 'A TV has an aspect ratio of 16:9. If the width is 32 inches, what is the height?', NULL, '[{"id":"a","text":"9 inches"},{"id":"b","text":"16 inches"},{"id":"c","text":"18 inches"},{"id":"d","text":"24 inches"}]'::jsonb, '"c"'::jsonb, '16:9 = 32:x. Cross multiply: 16x = 288 → x = 18 inches.', 'Set up the proportion: 16/9 = 32/?', 5, 2),
('44444444-0204-0004-0001-000000000003', '33333333-0204-0001-0001-000000000004', 'fill_in_blank', 'easy', 'A car travels 150 km in 2 hours. At this rate, how far will it go in 5 hours? (Type just the number)', NULL, NULL, '"375"'::jsonb, '150/2 = x/5. Cross multiply: 750 = 2x → x = 375 km.', 'Set up a proportion with distance and time', 5, 3),
('44444444-0204-0004-0001-000000000004', '33333333-0204-0001-0001-000000000004', 'fill_in_blank', 'medium', 'To make orange paint, you mix red and yellow in a 2:3 ratio. How many parts of yellow do you need if you use 8 parts of red?', NULL, NULL, '"12"'::jsonb, '2:3 = 8:x. Cross multiply: 2x = 24 → x = 12 parts yellow.', '2 is to 3 as 8 is to what?', 10, 4),
('44444444-0204-0004-0001-000000000005', '33333333-0204-0001-0001-000000000004', 'multiple_choice', 'easy', 'Thales of Miletus calculated the height of the Great Pyramid using which concept?', NULL, '[{"id":"a","text":"Calculus"},{"id":"b","text":"Ratios of shadows"},{"id":"c","text":"Trigonometric functions"},{"id":"d","text":"Logarithms"}]'::jsonb, '"b"'::jsonb, 'Thales used the ratio between an object''s height and its shadow length to calculate the pyramid''s height — one of the earliest practical uses of proportional reasoning.', 'He compared his own shadow to the pyramid''s shadow', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes) VALUES
('33333333-0204-0001-0001-000000000005', '22222222-0002-0001-0001-000000000004', 'Ratios Boss Round', 'Master ratios and proportions!', 5, 'boss_round', 25, 5)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0204-0005-0001-000000000001', '33333333-0204-0001-0001-000000000005', 'fill_in_blank', 'medium', 'Solve: 7/x = 21/15. What is x?', '\\frac{7}{x} = \\frac{21}{15}', NULL, '"5"'::jsonb, 'Cross multiply: 7 × 15 = 21x → 105 = 21x → x = 5.', 'Cross multiply and solve', 10, 1),
('44444444-0204-0005-0001-000000000002', '33333333-0204-0001-0001-000000000005', 'fill_in_blank', 'medium', 'If 5 workers can paint a fence in 8 hours, how many hours would 10 workers take? (Assume same rate)', NULL, NULL, '"4"'::jsonb, 'Double the workers = half the time. 5:8 → 10:4. This is an inverse proportion!', 'More workers means less time — divide, do not multiply', 10, 2),
('44444444-0204-0005-0001-000000000003', '33333333-0204-0001-0001-000000000005', 'multiple_choice', 'medium', 'A model car is built at a 1:24 scale. If the real car is 4.8 meters long, how long is the model?', NULL, '[{"id":"a","text":"0.1 m"},{"id":"b","text":"0.2 m"},{"id":"c","text":"0.5 m"},{"id":"d","text":"2 m"}]'::jsonb, '"b"'::jsonb, '4.8 ÷ 24 = 0.2 meters (20 cm). Scale models use ratios to shrink real objects proportionally.', 'Divide the real length by the scale factor', 10, 3),
('44444444-0204-0005-0001-000000000004', '33333333-0204-0001-0001-000000000005', 'fill_in_blank', 'medium', 'The ratio of boys to girls in a class is 3:5. If there are 24 students total, how many are boys?', NULL, NULL, '"9"'::jsonb, '3 + 5 = 8 parts total. Each part = 24 ÷ 8 = 3 students. Boys = 3 × 3 = 9.', 'Find how many students each "part" represents', 10, 4),
('44444444-0204-0005-0001-000000000005', '33333333-0204-0001-0001-000000000005', 'true_false', 'medium', 'True or False: The word "ratio" comes from the Latin word meaning "to reckon" or "to think."', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! The Latin root "reri" means to reckon or calculate. Ratio literally means "reckoning."', 'Think about the etymology from the Story section', 10, 5)
